sourcesContent:
import React from "react";
import styled from "styled-components";
import { Link } from "react-router-dom";
// import { Tablet } from "../Responsive";

const Wrapper = styled.div`
  font-family: "Poppins", sans-serif;
  margin: 0;
  padding: 0;
  background-color: black;
  color: white;

}
a:hover{
    color: rgba(219, 26, 165, 0.5);
    font-weight: 600;
 }
.content{
    display: flex;
    flex-direction: column;
    flex-wrap: wrap;
    ${Tablet({ flexDirection: "row" })}
}
.item{
    flex: 100%;
    ${Tablet({ flex: "22%" })}
}
.item h4{

}
.footerItem{
  margin: 20px 0;
}
.footerItem a{
   text-decoration: none;
   color: rgba(255, 255, 255, 0.7);

}
.contact div{
    display: flex;
    align-items: center;
    margin-bottom: 20px;
}
.contact span{
   color: rgba(255, 255, 255, 0.7);
   margin-left: 15px;
   font-size: 16px;
}
.contact .address-icon{
    height: 20px;
    width: 20px;
    color: white;
}
.item-brand{
      margin-right: 20px;
      ${Tablet({ marginTop: "20px" })}
 }
.footerlogo{
    display: flex;
}
.footerIcons{
    display: flex;
    align-items: center;
}
.rule{
    border: 2px solid white;
}
.copyWright {
    display: flex;
    justify-content: center;
    align-items: center;
  }
.copyWright p{
    margin: 0;
}
.icon{
    display: flex;
    justify-content: center;
    align-items: center;
    margin-right: 20px;
    border-radius: 50%;
    padding: 2px;
    width: 35px;
    height: 35px;
    color: var(--primary-color);
    background: white;
}
.footerIcons, h5{
    margin: 20px;
}

.brand{
    height: 20px;
    width: 20px;
}


/* for medium and large screen */
@media only screen and (min-width: 768px){
    .content{
      flex-direction: row;
    }
    .item{
        flex: 22%;
      }
    .item-brand{
        margin-top: 20px;
    }
 }
`;

function Footer() {
  return (
    <Wrapper>
      <div class="content">
        <div class="item">
          <div class="footerlogo">
            <Link href="/">
              <img
                src="/images/brand.png"
                alt="brand"
                height="40"
                width="40"
              />
            </Link>
            <h3 class="ms-2">Ahom Hotel</h3>
          </div>
          <div class="contact">
            <h5>Our Address</h5>
            <div class="mb-2"><i class="fa-solid fa-location-dot address-icon"></i>
              <span>No. 10 Howedy Street, Maitama, Abuja, Nigeria</span>
            </div>
            <div class="mb-2"><i class="fa-solid fa-phone address-icon"></i>
              <span>+2347066890098</span>
            </div>
            <div class="mb-2"><i class="fa-solid fa-envelope-circle-check address-icon"></i>
              <span>Info@ahomhotel.com</span>
            </div>
          </div>
          <h5>Follow Ahom on</h5>
          <div class="footerIcons">
            <div class="icon"><i class="fa-brands fa-facebook brand"></i></div>
            <div class="icon"><i class="fa-brands fa-x-twitter brand"></i></div>
            <div class="icon"><i class="fa-brands fa-instagram brand"></i></div>
            <div class="icon"><i class="fa-brands fa-youtube brand"></i></div>
          </div>

        </div>
        <div class="item">
          <h4>Company</h4>
          <div class="footerItem"><Link to="/">Home</Link></div>
          <div class="footerItem"><Link to="/about-us">About Us</Link></div>
          <div class="footerItem"><Link to="/contact-us">Contact Us</Link></div>
          <div class="footerItem"><Link to="/gallery">Gallery</Link></div>
          <div class="footerItem"><Link to="/rooms/all">Rooms</Link></div>
        </div>
        <div class="item">
          <h4>Services</h4>
          <div class="footerItem"><Link to="/contact-us">Room Bookings</Link></div>
          <div class="footerItem"><Link to="/contact-us">Event Reservations</Link></div>
          <div class="footerItem"><Link to="/contact-us">Restaurant</Link></div>
          <div class="footerItem"><Link to="/contact-us">Facilities</Link></div>
          <div class="footerItem"><Link to="/contact-us">Dining</Link></div>
        </div>
        <div class="item">
          <h4>Resources</h4>
          <div class="footerItem"><Link to="/terms">Terms of Service</Link></div>
          <div class="footerItem"><Link to="/privacy">Privacy Policy</Link></div>
        </div>
      </div>
      <hr class="rule" />
      <div class="copyWright">
        <p class="">Ahom &copy;
          <span>{new Date().getFullYear()}</span>, All Right Reserved to Idokoken
        </p>
      </div>
    </Wrapper>
  );
}

export default Footer;
